fn aba(a: Vec<i32>) -> Vec<i32> {
    // Preallocate the output vector with the same length as the input
    let mut b = Vec::with_capacity(a.len());
    
    // For each element in the input, compute its absolute value
    // (we assume no element is i32::MIN, so -(x) won't overflow)
    for x in a {
        let abs_x = if x < 0 { -x } else { x };
        b.push(abs_x);
    }
    
    b
}

